CREATE TABLE IF NOT EXISTS payment_eligibilities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,completion_certificate_id UUID NOT NULL,payment_trigger_rule_id UUID NOT NULL,eligible BOOLEAN NOT NULL,blockers JSONB NOT NULL,evaluated_by UUID NOT NULL,evaluated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS financial_entitlements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,payment_eligibility_id UUID NOT NULL REFERENCES payment_eligibilities(id),currency TEXT NOT NULL,gross_earned_amount_minor BIGINT NOT NULL CHECK(gross_earned_amount_minor>0),variations_amount_minor BIGINT NOT NULL,retention_amount_minor BIGINT NOT NULL,tax_amount_minor BIGINT NOT NULL,penalty_amount_minor BIGINT NOT NULL,net_payable_amount_minor BIGINT NOT NULL CHECK(net_payable_amount_minor>=0),status TEXT NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),calculated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,financial_entitlement_id UUID NOT NULL REFERENCES financial_entitlements(id),invoice_number TEXT NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('SUBMITTED','MATCHED','APPROVED','REJECTED')),submitted_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workspace_id,invoice_number));
CREATE TABLE IF NOT EXISTS funding_commitments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,provider_key TEXT NOT NULL,external_custody_reference TEXT NOT NULL,committed_amount_minor BIGINT NOT NULL CHECK(committed_amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING_CONFIRMATION','CONFIRMED','CANCELLED')),provider_confirmation_reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),confirmed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS fund_reservations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),funding_commitment_id UUID NOT NULL REFERENCES funding_commitments(id),invoice_id UUID NOT NULL REFERENCES invoices(id),reserved_amount_minor BIGINT NOT NULL CHECK(reserved_amount_minor>0),status TEXT NOT NULL CHECK(status IN('RESERVED','RELEASED','CANCELLED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS release_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,financial_entitlement_id UUID NOT NULL REFERENCES financial_entitlements(id),invoice_id UUID NOT NULL REFERENCES invoices(id),fund_reservation_id UUID NOT NULL REFERENCES fund_reservations(id),release_type TEXT NOT NULL CHECK(release_type IN('FULL','PARTIAL','STAGED')),requested_amount_minor BIGINT NOT NULL CHECK(requested_amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','CONDITIONS_MET','BLOCKED','CANCELLED')),blockers JSONB NOT NULL,requested_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payment_eligibilities_milestone_idx ON payment_eligibilities(workspace_id,milestone_id);CREATE INDEX IF NOT EXISTS financial_entitlements_milestone_idx ON financial_entitlements(workspace_id,milestone_id);CREATE INDEX IF NOT EXISTS invoices_entitlement_idx ON invoices(workspace_id,financial_entitlement_id);CREATE INDEX IF NOT EXISTS funding_commitments_milestone_idx ON funding_commitments(workspace_id,milestone_id);CREATE INDEX IF NOT EXISTS fund_reservations_commitment_idx ON fund_reservations(workspace_id,funding_commitment_id,status);CREATE INDEX IF NOT EXISTS release_requests_milestone_idx ON release_requests(workspace_id,milestone_id);
ALTER TABLE payment_eligibilities ENABLE ROW LEVEL SECURITY;ALTER TABLE financial_entitlements ENABLE ROW LEVEL SECURITY;ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;ALTER TABLE funding_commitments ENABLE ROW LEVEL SECURITY;ALTER TABLE fund_reservations ENABLE ROW LEVEL SECURITY;ALTER TABLE release_requests ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['payment_eligibilities','financial_entitlements','invoices','funding_commitments','fund_reservations','release_requests'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['payment_eligibilities','financial_entitlements','funding_commitments'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
